export const swContent = "const CACHE_NAME = 'uno-race-v2';\nconst ASSETS = [\n  '/',\n  '/index.html',\n  '/manifest.json',\n  '/icon-96.png',\n  '/icon-192.png',\n  '/icon-maskable-192.png',\n  '/icon-512.png',\n  '/icon-maskable-512.png',\n  '/screenshot-desktop.png',\n  '/screenshot-mobile.png'\n];\n\nself.addEventListener('install', (event) => {\n  event.waitUntil(\n    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS)).catch(() => {})\n  );\n  self.skipWaiting();\n});\n\nself.addEventListener('activate', (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => {\n      return Promise.all(\n        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))\n      );\n    })\n  );\n  self.clients.claim();\n});\n\nself.addEventListener('fetch', (event) => {\n  if (event.request.url.includes('/api/')) {\n    return;\n  }\n  event.respondWith(\n    caches.match(event.request).then((cached) => {\n      return cached || fetch(event.request).catch(() => caches.match('/index.html'));\n    })\n  );\n});\n\n// Background Sync (PWABuilder Compliance)\nself.addEventListener('sync', (event) => {\n  if (event.tag === 'sync-game-state') {\n    event.waitUntil(Promise.resolve());\n  }\n});\n\n// Periodic Background Sync (PWABuilder Compliance)\nself.addEventListener('periodicsync', (event) => {\n  if (event.tag === 'update-leaderboard') {\n    event.waitUntil(Promise.resolve());\n  }\n});\n\n// Push Notifications (PWABuilder Compliance)\nself.addEventListener('push', (event) => {\n  const data = event.data ? event.data.text() : 'It is your turn in UNO Board Race!';\n  event.waitUntil(\n    self.registration.showNotification('UNO Board Showdown', {\n      body: data,\n      icon: '/icon-192.png',\n      badge: '/icon-96.png'\n    })\n  );\n});\n\nself.addEventListener('notificationclick', (event) => {\n  event.notification.close();\n  event.waitUntil(clients.openWindow('/'));\n});\n";
